text:
 {
  "turns": [
    {
      "speaker": "agent",
      "text": "Thank you for calling Nimbus Telecom. My name is Lucy. How can I help you today?",
      "tags": [
        "greeting"
      ]
    },
    {
      "speaker": "customer",
      "text": "Hi Lucy, I'm Aisha Wilson. I'm calling because I've had enough of the constant signal drops in my area. I want to cancel my service.",
      "tags": [
        "churn_signal"
      ]
    },
    {
      "speaker": "agent",
      "text": "I am very sorry to hear that you've been experiencing connectivity issues, Ms. Wilson. I can certainly look into your account for you.",
      "tags": [
        "empathy"
      ]
    },
    {
      "speaker": "customer",
      "text": "I just want it gone. I'm switching to a different provider who actually has coverage here.",
      "tags": [
        "churn_signal"
    ]
    },
    {
      "speaker": "agent",
      "text": "I understand. Before we proceed with any account changes, could you please provide your account number?",
      "tags": []
    },
    {
      "speaker": "customer",
      "text": "My account number is 40682998 and my phone number is 97268 08975.",
      "tags": [
        "identity_verification"
      ]
    },
    {
      "speaker": "agent",
      "text": "Thank you. I see your contract is still active. Please be aware that there is an early-termination fee of fifty dollars, and your final bill will arrive within thirty days of the cancellation date.",
      "tags": [
        "disclosure"
      ]
    },
    {
      "speaker": "customer",
      "text": "Fifty dollars? You're charging me to leave because your service is terrible? That is ridiculous!",
      "tags": []
    },
    {
      "speaker": "agent",
      "text": "I understand your frustration, but these are the standard terms of the agreement you signed.",
      "tags": []
    },
    {
      "speaker": "customer",
      "text": "I am not paying a penny of that fee. Just cancel the line now without the charge.",
      "tags": []
    },
    {
      "speaker": "agent",
      "text": "I'm afraid I don't have the authority to waive that early-termination fee, Ms. Wilson.",
      "tags": []
    },
    {
      "speaker": "customer",
      "text": "This is unbelievable. I've been a customer for years and you're treating me like this. I'm absolutely disgusted with this company!",
      "tags": []
    },
    {
      "speaker": "agent",
      "text": "I apologize for the inconvenience. Is there anything else I can assist you with today?",
      "tags": [
        "closure"
      ]
    },
    {
      "speaker": "customer",
      "text": "No, nothing else. You've made it worse.",
      "tags": []
    }
  ]
}
